from . import delta_operations
from ta5g_scfc_analysis import ta5g_scfc_analysis
from robot.libraries.BuiltIn import BuiltIn
from ta5g_admin_operations import ta5g_admin_operations


def get_output_dir():
    return BuiltIn().get_variable_value('${OUTPUT_DIR}')


class ta5g_delta(object):
    def roll_delta_back(self, initial_scf_filename, delta_scf_filename, delta_directory=None):
        if ta5g_admin_operations().is_classical():
            delta_operations.roll_delta_back(initial_scf_filename, delta_scf_filename, get_output_dir(), delta_directory)
        else:
            delta_operations.roll_delta_back_aic(initial_scf_filename, delta_scf_filename)

    @staticmethod
    def build_full_scf_using_delta(full_scf_filename, delta_scf_filename):
        return delta_operations.build_full_scf_using_delta(full_scf_filename, delta_scf_filename, get_output_dir())

    @staticmethod
    def roll_back_to_initial_state(initial_scf_filename):
        delta_operations.roll_back_to_initial_state(
            initial_scf_filename, ta5g_scfc_analysis().get_latest_scfc(), get_output_dir()
        )
